const http   = require('http');
const https  = require('https');
const fs     = require('fs');
const path   = require('path');
const os     = require('os');

const PORT       = Number(process.env.PORT || 3001);
const HTTPS_PORT = Number(process.env.HTTPS_PORT || 3444);

// PFX cert generated by PowerShell New-SelfSignedCertificate
const PFX_PATH = path.join(__dirname, 'server.pfx');
const PFX_PASS = 'qrft2026';
function getLocalIP() {
  for (const ifaces of Object.values(os.networkInterfaces())) {
    for (const iface of ifaces) {
      if (iface.family === 'IPv4' && !iface.internal) return iface.address;
    }
  }
  return 'localhost';
}

function serveFile(res, filePath, contentType) {
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end('Not found'); return; }
    res.writeHead(200, { 'Content-Type': contentType });
    res.end(data);
  });
}

function requestHandler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') { res.writeHead(204); res.end(); return; }

  // Serve the QR sender by default; files move only through animated QR symbols.
  if (req.method === 'GET' && (req.url === '/' || req.url === '/index.html')) {
    serveFile(res, path.join(__dirname, 'sender.html'), 'text/html');
    return;
  }
  if (req.method === 'GET' && req.url === '/sender.html') {
    serveFile(res, path.join(__dirname, 'sender.html'), 'text/html');
    return;
  }
  if (req.method === 'GET' && req.url === '/receiver.html') {
    serveFile(res, path.join(__dirname, 'receiver.html'), 'text/html');
    return;
  }
  if (req.method === 'GET' && req.url === '/fountain.js') {
    serveFile(res, path.join(__dirname, 'fountain.js'), 'application/javascript');
    return;
  }
  if (req.method === 'GET' && req.url === '/jszip.min.js') {
    serveFile(res, path.join(__dirname, 'jszip.min.js'), 'application/javascript');
    return;
  }

  res.writeHead(404); res.end('Not found');
}

const server = http.createServer(requestHandler);

server.listen(PORT, '0.0.0.0', () => {
  const ip = getLocalIP();
  console.log('\n╔═══════════════════════════════════════════════════╗');
  console.log('║            QR File Transfer App                   ║');
  console.log('╠═══════════════════════════════════════════════════╣');
  console.log(`║  Sender (this PC):  http://localhost:${PORT}/            ║`);
  console.log(`║  Receiver (phone):  https://${ip}:${HTTPS_PORT}/   ║`);
  console.log('╚═══════════════════════════════════════════════════╝');
  console.log('\n📱 On the phone: open the https:// URL in Chrome');
  console.log('   First time: tap Advanced → Proceed to site (unsafe)\n');
});

// HTTPS server so Chrome on phone allows camera access
if (fs.existsSync(PFX_PATH)) {
  const tlsOptions = { pfx: fs.readFileSync(PFX_PATH), passphrase: PFX_PASS };
  https.createServer(tlsOptions, requestHandler).listen(HTTPS_PORT, '0.0.0.0');
} else {
  console.warn('⚠  server.pfx not found — HTTPS disabled. Phone camera may not work in Chrome.');
}